/** Forward only bounded diagnostics generated by our backend, never arbitrary headers. */
export function proxyDiagnosticHeaders(upstream: Headers, elapsedMs: number): Record<string, string> {
  const headers: Record<string, string> = {};
  const requestId: string | null = upstream.get('x-request-id');
  const cache: string | null = upstream.get('x-catalog-cache');
  const timing: string | null = upstream.get('server-timing');

  if (requestId && /^[a-f0-9]{32}$/.test(requestId)) {
    headers['X-Request-ID'] = requestId;
  }
  if (cache && ['HIT', 'MISS', 'BYPASS'].includes(cache)) {
    headers['X-Catalog-Cache'] = cache;
  }

  const proxyTiming: string = `proxy;dur=${Math.max(0, elapsedMs).toFixed(2)}`;
  headers['Server-Timing'] = timing && /^app;dur=\d{1,10}\.\d{2}, db;dur=\d{1,10}\.\d{2}$/.test(timing)
    ? `${timing}, ${proxyTiming}`
    : proxyTiming;
  return headers;
}
